import katex from './vendor/katex/katex.mjs';

const copy={
 zh:{title:'计算怎样才算通过？',intro:'先检查数值收敛、热量守恒和街道稳定性，再解释方案效果。横轴是数值迭代次数。',run:'计算设置',tail:'最近 500 次',all:'全程',baseline:'现状屋顶',retrofit:'冷屋顶',heat:'绝对热差 / %',iteration:'迭代次数',target:'项目目标',latest:'最后一次热差',heatTail:'200 次尾窗最大热差',pressure:'压力初始残差',temperature:'温度初始残差',velocity:'速度初始残差',turbulence:'湍流初始残差',speedSpread:'单个街道探针风速最大峰峰值',tempSpread:'单个街道探针温度最大峰峰值',simple:'SIMPLE 外层收敛',yes:'达到',no:'未达到',metric:'检查项',pass:'两组通过数值检查',pending:'两组尚未全部通过',scope:'把最后 200 次按中点分成前后两段，比较同一组 12 点的平均值，得到表中的半窗变化。数值通过用于本轮固定情景的概念展示；网格、范围、入口与实测验证分别保留。',formula:'热差公式与符号',eta:'ηQ 是无量纲热差，图上乘以 100 显示为百分比。越接近零，边界热量越接近平衡。这是稳态模型的数值预算差，不能解释为现场储热。',net:'Pnet 是全部物理边界的净向外热功率（W），包括屋顶的负输入项。正值表示排出多于输入，负值表示排出少于输入。',roof:'Proof 是屋顶规定输入的正热功率（W）。屋顶面积、日射、反照率与显热转换假设共同决定它。',rules:'必须连续 200 次满足热差小于 1%，同时达到全部外层残差目标和街道稳定性条件。某一条曲线过线或程序正常结束都不足以单独判定通过。',residual:'初始残差衡量当前场代回离散方程的剩余量，表中为无量纲数。线性求解的 final residual 只说明单次方程求解程度。',spread:'峰峰值是同一个探针在尾窗内最大值减最小值，再取 12 个探针中的最大值；用它检查局部是否仍在波动。',records:'下载检查记录 JSON',stamp:'检查时间',unavailable:'检查记录暂未加载'},
 en:{title:'When does a calculation pass?',intro:'Check numerical convergence, heat conservation and street stability before reading design effects. The horizontal axis counts solver iterations.',run:'Calculation',tail:'Last 500 iterations',all:'Full history',baseline:'Existing roofs',retrofit:'Cool roofs',heat:'Absolute heat gap / %',iteration:'Solver iteration',target:'Project target',latest:'Latest heat gap',heatTail:'Largest heat gap over 200 iterations',pressure:'Initial pressure residual',temperature:'Initial temperature residual',velocity:'Initial velocity residual',turbulence:'Initial turbulence residual',speedSpread:'Largest street-probe speed range',tempSpread:'Largest street-probe temperature range',simple:'SIMPLE outer convergence',yes:'Reached',no:'Not reached',metric:'Check',pass:'Both cases pass numerical checks',pending:'Both cases have not yet passed all checks',scope:'Half-window change compares the averages of the same 12 probes before and after the midpoint of the last 200 iterations. Numerical acceptance supports this fixed-scenario concept view. Mesh, extent, inlet and empirical validation remain separate.',formula:'Heat-gap equation and symbols',eta:'ηQ is a dimensionless heat gap. The chart multiplies it by 100 to show percent. Closer to zero means better boundary heat balance. This steady-model gap is numerical imbalance, not physical heat storage.',net:'Pnet is net outward heat power over all physical boundaries (W), including the negative roof input. Positive means more heat leaves than enters; negative means less leaves.',roof:'Proof is positive prescribed roof heat input (W). Roof area, sunlight, albedo and the assumed heat conversion set it.',rules:'The heat gap must stay below 1% for 200 iterations, with all outer residual targets and street stability checks also met. One low reading or a normal solver exit does not establish acceptance.',residual:'Initial residual measures the remaining mismatch when the current field enters a discrete equation; these values are dimensionless. Linear final residual describes one equation solve.',spread:'Probe range is maximum minus minimum at one probe over the tail window, then the largest of the 12 probes. It checks ongoing local variation.',records:'Download check records JSON',stamp:'Checked',unavailable:'Check records have not loaded'},
 ja:{title:'どの条件で計算が通過する？',intro:'数値収束・熱量保存・街路の安定性を確認してから計画効果を読みます。横軸は求解の反復回数です。',run:'計算設定',tail:'最後の500回',all:'全履歴',baseline:'現状屋根',retrofit:'高反射率屋根',heat:'絶対熱収支差 / %',iteration:'反復回数',target:'プロジェクト目標',latest:'最新の熱収支差',heatTail:'200回の窓内最大熱収支差',pressure:'圧力の初期残差',temperature:'温度の初期残差',velocity:'速度の初期残差',turbulence:'乱流の初期残差',speedSpread:'街路プローブ風速の最大変動幅',tempSpread:'街路プローブ温度の最大変動幅',simple:'SIMPLE外側収束',yes:'達成',no:'未達',metric:'確認項目',pass:'両案が数値確認を通過',pending:'両案とも全項目の通過には至っていません',scope:'前後半窓の差は最後の200回を中点で分け、同じ12点の平均値を比較します。数値通過は固定条件の概念表示用です。格子・範囲・流入・実測検証は別に確認します。',formula:'熱収支差の式と記号',eta:'ηQは無次元の熱収支差です。図では100倍して百分率で表示します。ゼロに近いほど境界の熱が釣り合います。定常モデルの数値的不均衡で、現地の蓄熱量を表しません。',net:'Pnetは全物理境界の正味外向き熱出力（W）で、屋根の負の入力項も含みます。正なら入力より排出が多く、負なら少ない状態です。',roof:'Proofは正の指定屋根熱入力（W）です。面積・日射・反射率・顕熱変換率の仮定で定まります。',rules:'200回の全てで熱収支差1%未満を満たし、外側残差と街路安定性も通過する必要があります。単一の低い値や正常終了だけでは判定できません。',residual:'初期残差は現在の場を離散方程式に入れた際の残りの不一致で、表では無次元です。線形final residualは一回の方程式求解を表します。',spread:'変動幅は各点の窓内最大値と最小値の差を取り、12点で最大の値を示します。局所変動が残るかを確認します。',records:'確認記録JSONを取得',stamp:'確認時刻',unavailable:'確認記録を読み込み中です'}
};
Object.assign(copy.zh,{normalEnd:'程序正常结束',coverage:'200 次热量与街道记录完整',speedDrift:'街道平均风速半窗变化',tempDrift:'街道平均温度半窗变化',turbulenceNote:'k 是湍流动能（m²/s²），ε 是耗散率（m²/s³）。本表展示它们方程的无量纲残差。'});
Object.assign(copy.en,{normalEnd:'Normal solver exit',coverage:'Complete 200-iteration heat and street history',speedDrift:'Street mean speed change between half-windows',tempDrift:'Street mean temperature change between half-windows',turbulenceNote:'k is turbulent kinetic energy (m²/s²); ε is its dissipation rate (m²/s³). This table shows their dimensionless equation residuals.'});
Object.assign(copy.ja,{normalEnd:'求解の正常終了',coverage:'200回の熱量・街路履歴が完全',speedDrift:'前後半窓の街路平均風速差',tempDrift:'前後半窓の街路平均温度差',turbulenceNote:'kは乱流運動エネルギー（m²/s²）、εは散逸率（m²/s³）です。表は方程式の無次元残差です。'});
let records=null;
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const svgNode=(tag,attrs,text)=>{const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;};
export async function loadNumericalChecks(){const r=await fetch('data/cfd-numerical-checks.json');if(!r.ok)throw Error('Numerical checks:'+r.status);records=await r.json();}

function chart(run,c,tail){
 const svg=svgNode('svg',{viewBox:'0 0 780 320',role:'img','aria-label':c.heat+'; '+c.iteration});
 svg.append(svgNode('title',{},c.heat));
 const all=Object.values(run.heat).flat(),end=Math.max(...all.map(p=>p[0])),start=tail?Math.max(0,end-500):0;
 const visible=all.filter(p=>p[0]>=start),top=Math.max(2,...visible.map(p=>p[1]*1.12));
 const x=n=>68+(n-start)/Math.max(1,end-start)*686,y=n=>265-n/top*220;
 for(let i=0;i<=4;i++){const v=top*i/4;svg.append(svgNode('line',{x1:68,x2:754,y1:y(v),y2:y(v),stroke:'#c5cec2','stroke-width':.7}),svgNode('text',{x:57,y:y(v)+4,'text-anchor':'end'},v<10?v.toFixed(1):v.toFixed(0)));}
 for(let i=0;i<=4;i++){const v=start+(end-start)*i/4;svg.append(svgNode('text',{x:x(v),y:285,'text-anchor':'middle'},Math.round(v)));}
 svg.append(svgNode('line',{x1:68,x2:754,y1:y(1),y2:y(1),stroke:'#7c7050','stroke-dasharray':'6 4','stroke-width':1.2}),svgNode('text',{x:750,y:Math.max(26,y(1)-7),'text-anchor':'end'},c.target+' < 1%'));
 for(const [name,color] of [['baseline','#a66c42'],['retrofit','#337788']]){const p=run.heat[name].filter(p=>p[0]>=start);svg.append(svgNode('path',{d:p.map(([a,b],i)=>(i?'L':'M')+x(a).toFixed(2)+','+y(b).toFixed(2)).join(' '),fill:'none',stroke:color,'stroke-width':2.5}));}
 svg.append(svgNode('text',{x:68,y:22},c.heat),svgNode('text',{x:412,y:313,'text-anchor':'middle'},c.iteration));return svg;
}

export function numericalReviewPanel(lang){
 const c=copy[lang]||copy.zh,box=node('section',undefined,'numerical-review');box.append(node('h3',c.title),node('p',c.intro));
 if(!records){box.append(node('p',c.unavailable));return box;}
 const toolbar=node('div',undefined,'numerical-toolbar'),label=node('label',c.run),select=node('select'),windowSelect=node('select');
 for(const run of records.runs){const option=node('option',run.label[lang]);option.value=run.key;select.append(option);}select.value=records.default_run;
 for(const [value,title] of [['tail',c.tail],['all',c.all]]){const option=node('option',title);option.value=value;windowSelect.append(option);}label.append(select);windowSelect.setAttribute('aria-label',lang==='zh'?'曲线显示范围':lang==='ja'?'曲線表示範囲':'Chart window');toolbar.append(label,windowSelect);
 const content=node('div');box.append(toolbar,content);
 const fmt=(v,unit='')=>v===null||v===undefined?'—':unit&&Math.abs(v)>0&&Math.abs(v)<.01?'< 0.01'+unit:((!unit&&Math.abs(v)>0&&Math.abs(v)<1)?v.toExponential(1):new Intl.NumberFormat({zh:'zh-CN',en:'en-GB',ja:'ja-JP'}[lang],{maximumFractionDigits:2}).format(v))+unit;
 function draw(){
  content.replaceChildren();const run=records.runs.find(r=>r.key===select.value),passed=run.checks.accepted_for_domain_comparisons;
  const status=node('p',passed?c.pass:c.pending,'numerical-status');status.dataset.check=passed?'pass':'pending';content.append(status,node('p',c.iteration+' · '+c.baseline+' '+run.checks.cases.baseline.last_completed_iteration+' / '+c.retrofit+' '+run.checks.cases.retrofit.last_completed_iteration,'run-snapshot'),node('small',c.stamp+' · '+new Date(run.checks.checked_utc).toLocaleString({zh:'zh-CN',en:'en-GB',ja:'ja-JP'}[lang],{timeZone:'Asia/Tokyo'})+' JST','run-snapshot'),chart(run,c,windowSelect.value==='tail'));
  const legend=node('div',undefined,'numerical-legend');for(const [key,color] of [['baseline','#a66c42'],['retrofit','#337788']]){const p=node('span',c[key]),i=node('i');i.style.background=color;p.prepend(i);legend.append(p);}content.append(legend);
  const table=node('table',undefined,'guide-table numerical-table'),head=node('tr');for(const t of [c.metric,c.target,c.baseline,c.retrofit])head.append(node('th',t));table.append(head);
  const policy=run.checks.policy,rows=[
   [c.normalEnd,'',r=>r.normal_end?'yes':'no',null],
   [c.simple,'',r=>r.SIMPLE_residual_control_reached?'yes':'no',null],
   [c.coverage,'',r=>r.heat.history_coverage&&r.street_probe_stability.history_coverage?'yes':'no',null],
   [c.latest,'%',r=>r.heat.latest_relative_imbalance*100,policy.heat.relative_imbalance_max_exclusive*100],
   [c.heatTail,'%',r=>r.heat.maximum_tail_relative_imbalance*100,policy.heat.relative_imbalance_max_exclusive*100],
   [c.pressure,'',r=>r.latest_initial_residuals.p_rgh,policy.outer_initial_residual_targets.p_rgh],
   [c.temperature,'',r=>r.latest_initial_residuals.T,policy.outer_initial_residual_targets.T],
   [c.velocity,'',r=>Math.max(...['Ux','Uy','Uz'].map(k=>r.latest_initial_residuals[k])),policy.outer_initial_residual_targets.U],
   [c.turbulence+' · k','',r=>r.latest_initial_residuals.k,policy.outer_initial_residual_targets.k],
   [c.turbulence+' · ε','',r=>r.latest_initial_residuals.epsilon,policy.outer_initial_residual_targets.epsilon],
   [c.speedDrift,' m/s',r=>r.street_probe_stability.half_window_mean_speed_change_ms,policy.probes.half_window_mean_speed_change_max_ms],
   [c.tempDrift,' K',r=>r.street_probe_stability.half_window_mean_temperature_change_K,policy.probes.half_window_mean_temperature_change_max_K],
   [c.speedSpread,' m/s',r=>r.street_probe_stability.maximum_probe_speed_peak_to_peak_ms,policy.probes.per_probe_speed_peak_to_peak_max_ms],
   [c.tempSpread,' K',r=>r.street_probe_stability.maximum_probe_temperature_peak_to_peak_K,policy.probes.per_probe_temperature_peak_to_peak_max_K]
  ];
  for(const [title,unit,read,limit] of rows){const row=node('tr');row.append(node('th',title),node('td',limit===null?c.yes:(unit==='%'?'< ':'≤ ')+fmt(limit,unit)));for(const name of ['baseline','retrofit']){const v=read(run.checks.cases[name]);let text=typeof v==='string'?c[v]:fmt(v,unit);if(typeof v==='number'){const rounded=unit?Math.round(v*100)/100:Number(v.toExponential(1));if(v>limit&&rounded<=limit)text='> '+fmt(limit,unit);if(v<limit&&rounded>=limit)text='< '+fmt(limit,unit);if(unit==='%'&&v===limit)text='≥ '+fmt(limit,unit);}const cell=node('td',text);cell.dataset.check=typeof v==='string'?(v==='yes'?'pass':'pending'):((unit==='%'?v<limit:v<=limit)?'pass':'pending');row.append(cell);}table.append(row);}content.append(table,node('p',c.rules),node('p',c.residual),node('p',c.turbulenceNote),node('p',c.spread),node('p',c.scope,'guide-status'));
 }
 select.addEventListener('change',draw);windowSelect.addEventListener('change',draw);draw();
 box.append(node('h4',c.formula));const formula=node('div',undefined,'lesson-math');katex.render('\\eta_Q=\\frac{|P_{\\mathrm{net}}|}{P_{\\mathrm{roof}}},\\qquad \\eta_Q<0.01',formula,{displayMode:true,throwOnError:true,output:'htmlAndMathml',trust:false});box.append(formula);for(const [tex,text] of [['\\eta_Q',c.eta.replace(/^ηQ/,'')],['P_{\\mathrm{net}}',c.net.replace(/^Pnet/,'')],['P_{\\mathrm{roof}}',c.roof.replace(/^Proof/,'')]]){const p=node('p'),symbol=node('span');katex.render(tex,symbol,{throwOnError:true,output:'htmlAndMathml',trust:false});p.append(symbol,document.createTextNode(text));box.append(p);}const link=node('a',c.records);link.href='data/cfd-numerical-checks.json';link.target='_blank';link.rel='noopener';box.append(link);return box;
}
